// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "../bridge";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** The end-user handbook's outline for the logged-in employee: only the workspaces, screens and tasks they may use. The help site shows exactly these pages and searches only them. */
export interface HandbookOut {
  user: string;
  roles: string[];
  /** The user's own workspaces first */
  workspaces: HandbookWorkspaceOut[];
  /** Login, the launcher, settings, notifications, approvals ... */
  shared_screens: HandbookScreenOut[];
  /** How many help pages this user may open */
  pages: number;
  guide: string;
  active_workspace: string | null;
  /** The questions the workspace FAQs must answer (guide 12, W3) */
  faq_seed: FaqSeedOut[];
  /** With print=true and a workspace: the printable guide's cover and chapters */
  print_edition: PrintEditionOut | null;
}

export interface HandbookWorkspaceOut {
  code: string;
  label: string;
  label_ur: string;
  description: string;
  /** The workspace's own page (a day in the role): workspaces/<code> */
  page: string;
  /** True: one of the user's roles lands here */
  yours: boolean;
  screens: HandbookScreenOut[];
}

/** A screen this user may use, as the handbook must describe it. */
export interface HandbookScreenOut {
  /** The screen id of the catalogue: the help page's id too */
  id: string;
  title: string;
  purpose: string;
  /** The business workflow section or MSDS indicators the screen serves */
  workflow: string;
  workspace: string;
  /** The help page the frontend writes for it: screens/<id> */
  page: string;
  /** Only the tasks this user may do */
  tasks: HandbookTaskOut[];
  /** What the screen does and refuses: the material of the page's 'how it works' */
  rules: string[];
  /** What updates on the screen by itself (realtime events) */
  events: string[];
  /** What the screen shows now (services: GET /establishment views) */
  view: "full" | "open_work" | "records" | "setup";
}

/** One thing the user may do on the screen: an endpoint the server lets this user call, in user words. */
export interface HandbookTaskOut {
  method: string;
  path: string;
  /** The task in plain words, e.g. 'Register a new patient' */
  summary: string;
  /** True: changes something (a button); false: a view */
  is_action: boolean;
}

/** A question a workspace's FAQ must answer (guide 12, W3): an error its screens can meet, or a state machine they move. */
export interface FaqSeedOut {
  /** workspace:error:CODE or workspace:state:entity */
  id: string;
  /** The workspace code, or * for the shared screens */
  workspace: string;
  /** The first screen that meets it */
  screen_id: string;
  kind: "error" | "state";
  /** The error code (kind error) */
  code: string | null;
  /** The state machine (kind state) */
  entity: string | null;
  question: string;
}

/** The printable user guide of one workspace: the cover, then a table of contents, then the chapters in order. */
export interface PrintEditionOut {
  cover: PrintCoverOut;
  chapters: PrintChapterOut[];
}

export interface PrintCoverOut {
  hospital: string;
  phc_number: string | null;
  phc_category: string | null;
  workspace: string;
  workspace_label: string;
  workspace_label_ur: string | null;
  /** The server's version: in every page footer with the date */
  version: string;
  generated_on: string;
}

export interface PrintChapterOut {
  number: number;
  kind: "workspace" | "screen" | "shared" | "faq";
  /** The help page the chapter prints (workspaces/<code>, screens/<id>, workspaces/<code>#faq) */
  page: string;
  title: string;
}

export interface MyPreferencesOut {
  theme: "Light" | "DarkHighContrast";
  language: "en" | "ur";
  ui_scale_pct: number;
  /** How a set of documents (the MSDS inspection pack) downloads: Separate = a button per document, one PDF each; Combined = one button, one PDF with all of them */
  pdf_download: "Separate" | "Combined";
  /** Anything else the frontend stores for this user */
  extra: Record<string, unknown>;
  /** Null until the user saves preferences for the first time */
  updated_at: string | null;
}

/** The end-user handbook's outline for the logged-in employee (only what they may use) — GET /api/v1/meta/handbook (who may call: any logged-in user, for their own account (also before a forced password change where allowed)). */
export function endUserHandbook(query?: { workspace?: string | null; print?: boolean }): Promise<HandbookOut> {
  return api<HandbookOut>("GET", withQuery(`/meta/handbook`, query), undefined);
}

/** My preferences (theme, language, UI scale, PDF download) — GET /api/v1/settings/me (who may call: any logged-in user, for their own account (also before a forced password change where allowed)). */
export function getPrefs(): Promise<MyPreferencesOut> {
  return api<MyPreferencesOut>("GET", `/settings/me`, undefined);
}
